#!/usr/bin/env bash
# Compile and upload the firmware. Reads Wi-Fi credentials (the drone's network) from esp32/.env.
# Usage: ./flash.sh [beacon|bridge] [serial-port]   (beacon by default; auto-detects the port if omitted)
set -euo pipefail
cd "$(dirname "$0")"

[ -f .env ] || { echo "Missing esp32/.env (copy .env.example)"; exit 1; }
set -a; source .env; set +a

SKETCH=beacon
case "${1:-}" in beacon|bridge) SKETCH=$1; shift ;; esac

cat > "$SKETCH/secrets.h" <<EOF
// Generated by flash.sh from .env. Do not commit.
#define WIFI_SSID "${WIFI_SSID}"
#define WIFI_PASS "${WIFI_PASS}"
EOF

PORT="${1:-$(ls /dev/cu.usbserial-* /dev/cu.wchusbserial* /dev/cu.SLAB_USBtoUART* 2>/dev/null | head -1 || true)}"
[ -n "$PORT" ] || { echo "No ESP32 serial port found"; exit 1; }

FQBN=esp32:esp32:esp32:UploadSpeed=115200  # 921600 is unreliable on this board
arduino-cli compile --fqbn "$FQBN" "$SKETCH"
arduino-cli upload --fqbn "$FQBN" -p "$PORT" "$SKETCH"
echo "Flashed $SKETCH to $PORT."
